import React, { useRef, useEffect, useCallback } from 'react';

const TOOLS = [
  { cmd: 'bold',          icon: 'B',  style: { fontWeight: 700 } },
  { cmd: 'italic',        icon: 'I',  style: { fontStyle: 'italic' } },
  { cmd: 'insertUnorderedList', icon: '≡', style: {} },
];

export default function SimpleEditor({ value, onChange, placeholder = 'Start writing…' }) {
  const ref = useRef();
  const isInternalChange = useRef(false);

  // Sync external value changes into the DOM (only on mount or external reset)
  useEffect(() => {
    if (!ref.current) return;
    if (ref.current.innerHTML !== value) {
      ref.current.innerHTML = value || '';
    }
  }, []); // intentionally only on mount

  const handleInput = useCallback(() => {
    if (!ref.current) return;
    onChange(ref.current.innerHTML);
  }, [onChange]);

  const execCmd = (cmd) => {
    ref.current?.focus();
    document.execCommand(cmd, false, null);
    handleInput();
  };

  const isEmpty = !value || value === '<br>' || value === '';

  return (
    <div style={{ border: '1px solid var(--paper-3)', borderRadius: 8, overflow: 'hidden' }}>
      {/* Toolbar */}
      <div style={{
        display: 'flex', gap: 2, padding: '6px 10px',
        borderBottom: '1px solid var(--paper-3)',
        background: 'var(--paper-2)',
      }}>
        {TOOLS.map(tool => (
          <button
            key={tool.cmd}
            onMouseDown={e => { e.preventDefault(); execCmd(tool.cmd); }}
            style={{
              width: 28, height: 28, borderRadius: 5,
              fontSize: 12, color: 'var(--ink-2)',
              border: '1px solid transparent',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              ...tool.style,
            }}
            onMouseEnter={e => { e.currentTarget.style.background = 'var(--paper-3)'; }}
            onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; }}
          >
            {tool.icon}
          </button>
        ))}
        <div style={{ flex: 1 }} />
        <span style={{ fontSize: 10, color: 'var(--ink-4)', alignSelf: 'center', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>
          ⌘B bold · ⌘I italic
        </span>
      </div>

      {/* Editable area */}
      <div style={{ position: 'relative' }}>
        {isEmpty && (
          <div style={{
            position: 'absolute', top: 14, left: 16,
            fontSize: 14, color: 'var(--ink-4)', fontStyle: 'italic',
            pointerEvents: 'none', lineHeight: 1.7,
          }}>
            {placeholder}
          </div>
        )}
        <div
          ref={ref}
          contentEditable
          suppressContentEditableWarning
          onInput={handleInput}
          style={{
            minHeight: 200,
            padding: '14px 16px',
            fontSize: 14,
            lineHeight: 1.75,
            color: 'var(--ink)',
            outline: 'none',
            fontFamily: 'var(--font-serif)',
          }}
        />
      </div>
    </div>
  );
}
